-- ─── 1) table (11 persisted → 16 ENV columns + provenance/audit) ──────────

create table safety.emergency_light_check (
    -- ENV 8-hex id (UI crypto); the seed sets id = the AppSheet row_ID
    -- verbatim (both 8-hex UNIQUEID() shapes) with legacy_id mirroring it
    -- (house traceability convention).
    id                 text PRIMARY KEY,
    legacy_id          text UNIQUE,
    -- AppSheet Date_time (Label, init =now() form-only — NO DB default,
    -- P2.1 D1-6 rule; UI default = today). DATE-ONLY at source (D1-4).
    check_date         date NOT NULL,
    -- AppSheet QR_CODE (init ="สแกน QR CODE") — the scanned/typed code
    -- verbatim; placeholder/blank/in-master Valid If semantics are
    -- enforced by the resolve RPC + form (fail-closed), not a DB
    -- constraint.
    erl_payload        text NOT NULL,
    -- Resolution — the AppSheet location auto-fill's reference, resolved
    -- EXACT at write time; NULL when unresolved (the seeded '31' row).
    light_id           text REFERENCES safety.emergency_light(erl_id),
    -- Auto-fill COPY semantics (snapshot at check time); blank ⇒ NULL.
    location_snapshot  text,                    -- AppSheet location
    -- Inspection enums — DOCUMENTED verbatim, NO hard CHECK (D1-2):
    --   persistency   มี / ไม่มี            (init =มี, form-only)
    --   position      เหมาะสม / ไม่เหมาะสม  (init =เหมาะสม, form-only)
    --   test_result   ผ่าน / ไม่ผ่าน        (init =ผ่าน, form-only;
    --                                        Show If persistency=มี is a
    --                                        UI visibility gate only)
    persistency        text NOT NULL,
    position           text NOT NULL,
    test_result        text NOT NULL,
    -- PII pin (D1-3 CLOSED — R2 PR #210 repair): the single distinct
    -- 13-digit Auditor account NEVER enters this repo. auditor_id carries
    -- the resolved core.personnel UUID when a deterministic match exists,
    -- else NULL; auditor_legacy_id exists for a NON-national-ID legacy
    -- identifier slot and stays NULL under the same pin. This seed: ALL
    -- NULL (no deterministic match — disclosure count in the handoff).
    auditor_id         uuid REFERENCES core.personnel(id),
    auditor_legacy_id  text,
    -- AppSheet Broken_detail EnumList (5 documented values) + free text
    -- observed at source — NO CHECK, verbatim " , " joins preserved.
    broken_detail      text,
    -- AppSheet Pic — legacy Drive-relative refs verbatim for the seed;
    -- new UI entries store the house Storage path (core.attachment).
    pic_path           text,
    -- AppSheet Status enum แจ้งซ่อม/แจ้งย้ายตำแหน่ง/ขอติดตั้ง; blank ⇒ NULL.
    status             text,
    source_provenance  text NOT NULL DEFAULT 'manual entry (ENV-PARITY-P2-003)',
    created_at         timestamptz NOT NULL DEFAULT now()
);

-- ─── 2) RLS + policies (house shapes) ─────────────────────────────────────

alter table safety.emergency_light_check enable row level security;

drop policy if exists emergency_light_check_read on safety.emergency_light_check;
create policy emergency_light_check_read
    on safety.emergency_light_check for select to authenticated
    using (core.fn_is_staff_or_admin());

drop policy if exists emergency_light_check_insert_staff on safety.emergency_light_check;
create policy emergency_light_check_insert_staff
    on safety.emergency_light_check for insert to authenticated
    with check (core.fn_is_staff_or_admin());

drop policy if exists emergency_light_check_update_admin on safety.emergency_light_check;
create policy emergency_light_check_update_admin
    on safety.emergency_light_check for update to authenticated
    using (core.fn_is_admin())
    with check (core.fn_is_admin());

drop policy if exists emergency_light_check_delete_admin on safety.emergency_light_check;
create policy emergency_light_check_delete_admin
    on safety.emergency_light_check for delete to authenticated
    using (core.fn_is_admin());

grant select, insert, update, delete on safety.emergency_light_check to authenticated;
-- NO anon policies → anonymous access is fail-closed by RLS (house rule).

-- ─── 3) QR resolve RPC (WO §4 — mirrors of the AppSheet initial-value
--        copies; P2.2 §11.2 binding: SECURITY INVOKER — RLS respected) ──

create or replace function safety.fn_resolve_emergency_light_qr(p_qr text)
returns jsonb
language plpgsql
security invoker
set search_path = safety, core, public
as $$
DECLARE
    v_qr  text;
    v_row safety.emergency_light%rowtype;
    v_count bigint;
    v_latest safety.emergency_light_check%rowtype;
BEGIN
    v_qr := coalesce(btrim(p_qr), '');
    IF v_qr = '' THEN
        RAISE EXCEPTION 'ไม่พบข้อมูล!!  ให้ถามเอ นะจ๊ะ';
    END IF;

    -- SECURITY INVOKER: the P2.1 master SELECT policy
    -- (core.fn_is_staff_or_admin()) gates this read — a non-staff caller
    -- sees no row and gets the same fail-closed error. EXACT match, never
    -- numeric-coerced, never case-folded (the historical non-padded '31'
    -- payload has no master row and must stay unresolved).
    SELECT * INTO v_row FROM safety.emergency_light WHERE erl_id = v_qr;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ไม่พบข้อมูล!!  ให้ถามเอ นะจ๊ะ';
    END IF;

    -- Prior-check summary (the re_check REF_ROWS semantics; the SortKey
    -- transcription order: check_date DESC + deterministic id tiebreak).
    SELECT count(*) INTO v_count FROM safety.emergency_light_check
     WHERE light_id = v_row.erl_id OR erl_payload = v_row.erl_id;

    SELECT * INTO v_latest FROM safety.emergency_light_check
     WHERE light_id = v_row.erl_id OR erl_payload = v_row.erl_id
     ORDER BY check_date DESC, id DESC
     LIMIT 1;

    RETURN jsonb_build_object(
        'master', jsonb_build_object(
            'erl_id',         v_row.erl_id,
            'location',       v_row.location,
            'location_floor', v_row.location_floor,
            'providers',      v_row.providers,
            'receive_date',   v_row.receive_date
        ),
        'prior', CASE WHEN v_count = 0 THEN jsonb_build_object(
            'check_count', 0, 'latest_check_date', NULL, 'latest_test_result', NULL
        ) ELSE jsonb_build_object(
            'check_count',        v_count,
            'latest_check_date',  v_latest.check_date,
            'latest_test_result', v_latest.test_result
        ) END
    );
END;
$$;

-- PostgREST façade wrapper (PostgREST exposes only `public`; same shape
-- as the public.fn_resolve_extinguisher_qr precedent). Still SECURITY
-- INVOKER — RLS applies end to end.
create or replace function public.fn_resolve_emergency_light_qr(p_qr text)
returns jsonb
language plpgsql
security invoker
set search_path = safety, core, public
as $$
BEGIN
    RETURN safety.fn_resolve_emergency_light_qr(p_qr);
END;
$$;

-- Standard execute grants: revoked from PUBLIC/anon, granted to
-- authenticated (function ACLs default to PUBLIC — pin them).
revoke all on function safety.fn_resolve_emergency_light_qr(text) from public;
revoke all on function safety.fn_resolve_emergency_light_qr(text) from anon;
grant execute on function safety.fn_resolve_emergency_light_qr(text) to authenticated;
revoke all on function public.fn_resolve_emergency_light_qr(text) from public;
revoke all on function public.fn_resolve_emergency_light_qr(text) from anon;
grant execute on function public.fn_resolve_emergency_light_qr(text) to authenticated;

-- ─── 4) public façades (security_invoker — base RLS always applies) ───────
-- The check view serves the staff list/form; the MASTER view is new in
-- this lane (P2.1 shipped none — P2.2 precedent: the manual pick list
-- needs REST reachability) through the UNCHANGED P2.1 policies.

create view public.emergency_light_check with (security_invoker=on)
    as select * from safety.emergency_light_check;
create view public.emergency_light with (security_invoker=on)
    as select * from safety.emergency_light;

grant select, insert, update, delete on public.emergency_light_check to authenticated;
grant select, insert, update, delete on public.emergency_light to authenticated;

